package main

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
	"sync"
	"time"
)

// DeliveryBackoff is the base backoff duration between retry attempts.
// Configurable for tests (e.g., set to 10*time.Millisecond).
var DeliveryBackoff = 100 * time.Millisecond

// maxDeliveryAttempts is the total number of attempts (initial + retries).
const maxDeliveryAttempts = 3

type webhookJob struct {
	URL      string          `json:"url"`
	Payload  json.RawMessage `json:"payload"`
	Attempts int
}

type stats struct {
	mu        sync.Mutex
	delivered int64
	failed    int64
	pending   int64
}

func (s *stats) incPending() {
	s.mu.Lock()
	s.pending++
	s.mu.Unlock()
	webhookPending.Inc()
}

func (s *stats) decPending() {
	s.mu.Lock()
	s.pending--
	s.mu.Unlock()
	webhookPending.Dec()
}

func (s *stats) incDelivered() {
	s.mu.Lock()
	s.delivered++
	s.mu.Unlock()
	webhookDeliveriesTotal.Inc()
}

func (s *stats) incFailed() {
	s.mu.Lock()
	s.failed++
	s.mu.Unlock()
	webhookFailuresTotal.Inc()
}

func (s *stats) snapshot() (delivered, failed, pending int64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.delivered, s.failed, s.pending
}

type store struct {
	mu   sync.Mutex
	jobs chan *webhookJob
	stats
	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup
}

func newStore() *store {
	ctx, cancel := context.WithCancel(context.Background())
	s := &store{
		jobs:   make(chan *webhookJob, 100),
		ctx:    ctx,
		cancel: cancel,
	}
	s.wg.Add(1)
	go s.worker()
	return s
}

func (s *store) enqueue(job *webhookJob) {
	s.incPending()
	select {
	case s.jobs <- job:
	case <-s.ctx.Done():
		s.decPending()
	}
}

func (s *store) worker() {
	defer s.wg.Done()
	for {
		select {
		case job := <-s.jobs:
			s.deliver(job)
		case <-s.ctx.Done():
			return
		}
	}
}

func (s *store) deliver(job *webhookJob) {
	defer s.decPending()

	client := &http.Client{Timeout: 5 * time.Second}

	for attempt := 1; attempt <= maxDeliveryAttempts; attempt++ {
		job.Attempts = attempt
		req, err := http.NewRequestWithContext(s.ctx, http.MethodPost, job.URL, nil)
		if err != nil {
			if attempt == maxDeliveryAttempts {
				s.incFailed()
			}
			continue
		}
		req.Header.Set("Content-Type", "application/json")
		req.Body = &nopCloser{bytes: job.Payload}

		resp, err := client.Do(req)
		if err != nil {
			if attempt == maxDeliveryAttempts {
				s.incFailed()
			} else {
				select {
				case <-time.After(DeliveryBackoff):
				case <-s.ctx.Done():
					s.incFailed()
					return
				}
			}
			continue
		}
		resp.Body.Close()

		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
			s.incDelivered()
			return
		}

		if attempt == maxDeliveryAttempts {
			s.incFailed()
			return
		}

		select {
		case <-time.After(DeliveryBackoff):
		case <-s.ctx.Done():
			s.incFailed()
			return
		}
	}
}

func (s *store) shutdown() {
	s.cancel()
	s.wg.Wait()
}

type nopCloser struct {
	bytes []byte
}

func (n *nopCloser) Read(p []byte) (int, error) {
	if len(n.bytes) == 0 {
		return 0, io.EOF
	}
	n := copy(p, n.bytes)
	n.bytes = n.bytes[n:]
	return n, nil
}

func (n *nopCloser) Close() error { return nil }

func registerRoutes(mux *http.ServeMux) {
	s := newStore()

	mux.HandleFunc("POST /webhooks", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			URL     string          `json:"url"`
			Payload json.RawMessage `json:"payload"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "malformed JSON", http.StatusBadRequest)
			return
		}
		if req.URL == "" {
			http.Error(w, "missing url", http.StatusBadRequest)
			return
		}
		u, err := url.Parse(req.URL)
		if err != nil || u.Scheme != "http" && u.Scheme != "https" || u.Host == "" {
			http.Error(w, "invalid url", http.StatusBadRequest)
			return
		}
		if req.Payload == nil {
			req.Payload = json.RawMessage("{}")
		}

		job := &webhookJob{
			URL:     req.URL,
			Payload: req.Payload,
		}
		s.enqueue(job)

		w.WriteHeader(http.StatusAccepted)
		json.NewEncoder(w).Encode(map[string]string{"status": "queued"})
	})

	mux.HandleFunc("GET /webhooks/stats", func(w http.ResponseWriter, r *http.Request) {
		delivered, failed, pending := s.stats.snapshot()
		json.NewEncoder(w).Encode(map[string]int64{
			"delivered": delivered,
			"failed":    failed,
			"pending":   pending,
		})
	})

	// Store cleanup on server shutdown would be ideal but not required for tests
	_ = s
}

