func TestWebhookInvalidRequests(t *testing.T) {
	// Reset metrics for test isolation
	webhookDeliveriesTotal.Reset()
	webhookFailuresTotal.Reset()
	webhookPending.Set(0)

	// Save and restore backoff
	origBackoff := DeliveryBackoff
	DeliveryBackoff = 10 * time.Millisecond
	defer func() { DeliveryBackoff = origBackoff }()

	srv := httptest.NewServer(newServer())
	defer srv.Close()

	client := &http.Client{Timeout: 5 * time.Second}

	// Test 1: missing url
	body := `{"payload": {}}`
	resp, err := client.Post(srv.URL+"/webhooks", "application/json", nil)
	if err != nil {
		t.Fatal(err)
	}
	if resp.StatusCode != http.StatusBadRequest {
		t.Errorf("expected 400 for missing url, got %d", resp.StatusCode)
	}
	resp.Body.Close()

	// Test 2: invalid url
	body = `{"url": "not-a-url", "payload": {}}`
	req, _ := http.NewRequest("POST", srv.URL+"/webhooks", nil)
	req.Header.Set("Content-Type", "application/json")
	resp, err = client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	if resp.StatusCode != http.StatusBadRequest {
		t.Errorf("expected 400 for invalid url, got %d", resp.StatusCode)
	}
	resp.Body.Close()
}

func TestWebhookValidRequestQueued(t *testing.T) {
	webhookDeliveriesTotal.Reset()
	webhookFailuresTotal.Reset()
	webhookPending.Set(0)

	origBackoff := DeliveryBackoff
	DeliveryBackoff = 10 * time.Millisecond
	defer func() { DeliveryBackoff = origBackoff }()

	srv := httptest.NewServer(newServer())
	defer srv.Close()

	client := &http.Client{Timeout: 5 * time.Second}

	body := `{"url": "http://127.0.0.1:1/x", "payload": {"a": 1}}`
	req, _ := http.NewRequest("POST", srv.URL+"/webhooks", nil)
	req.Header.Set("Content-Type", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	if resp.StatusCode != http.StatusAccepted {
		t.Errorf("expected 202, got %d", resp.StatusCode)
	}
	resp.Body.Close()

	// Check stats
	resp, err = client.Get(srv.URL + "/webhooks/stats")
	if err != nil {
		t.Fatal(err)
	}
	var stats map[string]int64
	json.NewDecoder(resp.Body).Decode(&stats)
	resp.Body.Close()

	if stats["pending"] != 1 {
		t.Errorf("expected pending=1, got %d", stats["pending"])
	}
	if stats["delivered"] != 0 {
		t.Errorf("expected delivered=0, got %d", stats["delivered"])
	}
	if stats["failed"] != 0 {
		t.Errorf("expected failed=0, got %d", stats["failed"])
	}
}

